 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {private int window=900;Actor(ServerLevel world){super(world,new com.mojang.authlib.GameProfile(UUID.fromString("9079315d-4c0b-429f-bd99-e427c761b940"),"CanonicalSegmented"));}@Override public boolean mayUseItemAt(BlockPos p,Direction face,ItemStack stack){return !p.equals(denied)&&super.mayUseItemAt(p,face,stack);}@Override public OptionalInt openMenu(MenuProvider provider,java.util.function.Consumer<net.minecraft.network.RegistryFriendlyByteBuf> writer){containerMenu=provider.createMenu(++window,getInventory(),this);need(containerMenu instanceof NativeSegmentedMenu&&containerMenu.getType()==BuiltInRegistries.MENU.get(ID),"actual registered dedicated editor factory");var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),serverLevel().registryAccess());try{writer.accept(buffer);need(buffer.readBlockPos().equals(((NativeSegmentedMenu)containerMenu).tile.getBlockPos())&&!buffer.isReadable(),"registered editor position buffer");}finally{buffer.release();}return OptionalInt.of(window);}}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(tracked!=null&&!event.isCanceled()&&!event.getLevel().isClientSide()&&event.getEntity() instanceof ItemEntity e&&e.position().distanceToSqr(Vec3.atCenterOf(tracked))<9)drops.add(e.getItem().copy());}
 private static void near(BlockPos p){actor.setPos(p.getX()+.5,p.getY()+.5,p.getZ()-2.5);actor.setYRot(0);actor.setXRot(0);actor.setShiftKeyDown(false);}
