 private static void place(BlockPos p,ItemStack held){world.getChunkAt(p);world.setChunkForced(p.getX()>>4,p.getZ()>>4,true);near(p);actor.setItemInHand(InteractionHand.MAIN_HAND,held);var click=new BlockHitResult(new Vec3(p.getX()+.5,p.getY(),p.getZ()+.5),Direction.UP,p.below(),false);int before=held.getCount();need(actor.gameMode.useItemOn(actor,world,held,InteractionHand.MAIN_HAND,click).consumesAction()&&held.getCount()==before-1,"real canonical survival item placement consumes exactly one");var tile=host(p);need(tile!=null&&tile.getClass()==NativeSegmentedDoorEntity.class&&tile.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(ID),"actual public block-entity factory and type");}
 private static void registrations(){need(BuiltInRegistries.BLOCK.containsKey(ID)&&BuiltInRegistries.ITEM.containsKey(ID),"public activation candidate required");need(item().getClass()==NativeSegmentedItem.class&&item().getBlock()==block(),"actual public canonical item class");var state=block().defaultBlockState();need(state.is(BlockTags.MINEABLE_WITH_PICKAXE)&&state.is(BlockTags.NEEDS_STONE_TOOL)&&state.requiresCorrectToolForDrops(),"production harvest properties/tags");need(new ItemStack(Items.STONE_PICKAXE).isCorrectToolForDrops(state)&&!new ItemStack(Items.WOODEN_PICKAXE).isCorrectToolForDrops(state),"production minimum stone tool");var tab=BuiltInRegistries.CREATIVE_MODE_TAB.get(ResourceLocation.fromNamespaceAndPath("vandorlabs","vandorlabs"));tab.buildContents(new CreativeModeTab.ItemDisplayParameters(world.enabledFeatures(),false,world.registryAccess()));need(tab.getDisplayItems().stream().filter(s->s.is(item())).count()==1,"one public item in actual creative enumeration");var recipe=(net.minecraft.world.item.crafting.CraftingRecipe)world.getRecipeManager().byKey(ID).orElseThrow().value();var ingredients=new ArrayList<ItemStack>();for(int i=0;i<9;i++)ingredients.add(new ItemStack(i==3||i==5?Items.PISTON:i==4?Items.REDSTONE:Items.IRON_INGOT));var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,ingredients);need(recipe.matches(input,world)&&recipe.assemble(input,world.registryAccess()).is(item())&&recipe.assemble(input,world.registryAccess()).getCount()==8,"actual source 3x3 recipe and eight output");for(String path:new String[]{"blockstates/segmented_door.json","models/item/segmented_door.json","lang/en_us.json"})try(var stream=SegmentedCanonicalChecks.class.getResourceAsStream("/assets/vandorlabs/"+path)){need(stream!=null,"actual packaged resource "+path);}catch(java.io.IOException failure){throw new IllegalStateException(failure);}}
 private static JsonArray values(NativeSegmentedDoorEntity t){JsonArray a=new JsonArray();var s=t.settings();for(int v:new int[]{t.topOffset(),t.height(),t.column(),t.columnsCount(),t.ticksPerSection(),t.texture(),t.duration(),(int)t.sequence(),s.direction,s.layout,s.activation,s.shape,s.position})a.add(v);for(boolean b:new boolean[]{t.formed(),t.configured(),t.targetOpen(),t.localRedstone(),t.signalOpens(),s.straight,s.window,s.join})a.add(b);a.add(t.initialPose());a.add(t.started());a.add(t.pose(0));return a;}
 private static void installOld(JsonObject profile,BlockPos top,boolean retain){int width=profile.get("width").getAsInt(),height=profile.get("height").getAsInt();clear(top);var tags=profile.getAsJsonArray("nbt");for(int x=0;x<width;x++)for(int row=0;row<height;row++){BlockPos p=top.offset(x,-row,0);world.getChunkAt(p);world.setChunkForced(p.getX()>>4,p.getZ()>>4,true);world.setBlock(p,block().defaultBlockState(),2);CompoundTag tag;try{tag=TagParser.parseTag(tags.get(x*height+row).getAsString());}catch(com.mojang.brigadier.exceptions.CommandSyntaxException e){throw new IllegalStateException(e);}if(retain&&x==0&&row==0){var caps=new CompoundTag();caps.putString("Owner","previous-segmented");tag.put("ForgeCaps",caps);CompoundTag fluids=new CompoundTag(),known=new CompoundTag(),opaque=new CompoundTag();known.putString("FluidName","water");known.putInt("Amount",1000);var payload=new CompoundTag();payload.putString("Previous","tagged-water");known.put("Tag",payload);opaque.putString("FluidName","missing:previous_segmented");opaque.putInt("Amount",713);opaque.putString("Payload","opaque-fluid");fluids.put("Side0",known);fluids.put("Side1",opaque);fluids.putString("FutureFluidSchema","retain-envelope");tag.put(NativeFluidSlots.KEY,fluids);}var loaded=BlockEntity.loadStatic(p,world.getBlockState(p),tag,world.registryAccess());need(loaded!=null&&loaded.getClass()==NativeSegmentedDoorEntity.class&&loaded.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(ID),"actual canonical factory loads previous emitted tile NBT");world.setBlockEntity(loaded);need(loaded.getBlockPos().equals(p),"native supplied position owns relocated old coordinates");}}
 private static void oldLayouts(){int count=0;for(var profile:source){String state=profile.get("stage").getAsString();((net.minecraft.world.level.storage.ServerLevelData)world.getLevelData()).setGameTime(state.equals("part")||state.equals("reverse")?5:0);installOld(profile,BASE,false);int width=profile.get("width").getAsInt(),height=profile.get("height").getAsInt();var values=profile.getAsJsonArray("tiles");for(int x=0;x<width;x++)for(int row=0;row<height;row++)need(values(host(BASE.offset(x,-row,0))).equals(values.get(x*height+row)),"actual previous emitted scalar layout stage="+state+" direction="+profile.get("direction"));count++;}need(count==72,"all previous source layouts including missing/clamped defaults");clear(BASE);}
 private static void menu(BlockPos p,boolean tool){near(p);actor.setGameMode(GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,tool?new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()):ItemStack.EMPTY);actor.setShiftKeyDown(!tool);need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit(p)).consumesAction()&&actor.containerMenu instanceof NativeSegmentedMenu m&&m.tile==host(p),"actual "+(tool?"Configurizer":"survival sneaking")+" opens same selected-section menu");actor.setShiftKeyDown(false);}
 private static void edit(int activation,int direction,boolean straight){var p=RUNTIME.east(1);menu(p,true);var tile=host(p);var old=tile.settings();var settings=new NativeSegmentedDoorSettings(direction,straight,2,activation,true,2,true,new com.vandorlabs.neoforge.door.NativeDoorGlass(-1,2,1,2),1);need(NativeSegmentedMenu.apply(actor,new NativeSegmentedEdit(actor.containerMenu.containerId,5,5,false,true,ChannelList.of(77701),-1,settings)),"actual registered per-section settings edit");need(!NativeSegmentedMenu.apply(actor,new NativeSegmentedEdit(actor.containerMenu.containerId+1,5,5,false,true,ChannelList.EMPTY,-1,settings)),"stale window refused");for(int x=0;x<3;x++)for(int y=0;y<3;y++){var t=host(RUNTIME.offset(x,y,0));need(t.settings().window==t.getBlockPos().equals(p)&&t.settings().direction==direction&&t.settings().straight==straight&&t.settings().position==1&&t.settings().layout==2,"per-row window and shared mechanism preserved");}denied=RUNTIME.east(2).above(2);boolean refused=false;try{NativeSegmentedMenu.apply(actor,new NativeSegmentedEdit(actor.containerMenu.containerId,4,5,false,true,ChannelList.EMPTY,-1,settings.activation(2)));}catch(IllegalArgumentException expected){refused=true;}finally{denied=null;}need(refused&&tile.settings().activation==activation,"distant protected member refuses atomic edit");menu(p,false);}
 private static void operate(boolean open){need(NativeSegmentedMenu.apply(actor,new NativeSegmentedEdit(actor.containerMenu.containerId,open?1:2,5,false,true,ChannelList.of(77701),-1,null)),"actual menu authoritative open/close");start=world.getGameTime();}
 private static void settled(boolean open){UUID motion=host(RUNTIME.above(2)).publication().motion().motionIdentity();for(int x=0;x<3;x++)for(int y=0;y<3;y++){var t=host(RUNTIME.offset(x,y,0));need(t.targetOpen()==open&&t.pose(0)==(open?1:0)&&Objects.equals(t.publication().motion().motionIdentity(),motion),"actual registered ticker settles all rows/columns with one timeline");}}
 private static void mining(){for(Item tool:new Item[]{Items.WOODEN_PICKAXE,Items.STONE_PICKAXE}){clear(BASE);world.setBlock(BASE.below(),Blocks.STONE.defaultBlockState(),2);actor.setGameMode(GameType.SURVIVAL);var held=new ItemStack(item(),2);place(BASE,held);var clone=block().getCloneItemStack(world.getBlockState(BASE),hit(BASE),world,BASE,actor);need(clone.is(item())&&clone.get(DataComponents.CUSTOM_DATA).copyTag().contains("BlockEntityTag"),"canonical configured pick");tracked=BASE;drops.clear();actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(tool));need(actor.gameMode.destroyBlock(BASE),"actual survival harvest");int count=drops.stream().filter(s->s.is(item())).mapToInt(ItemStack::getCount).sum();need(count==(tool==Items.STONE_PICKAXE?1:0),"production correct/wrong tool drop count");for(var drop:drops)if(drop.is(item()))need(!drop.has(DataComponents.CUSTOM_DATA)&&!drop.has(DataComponents.BLOCK_ENTITY_DATA),"source ordinary survival loot remains plain");tracked=null;}}
 private static List<JsonObject> savedProfiles(){return source.stream().filter(p->p.get("stage").getAsString().equals("part")).toList();}
 private static void saveOld(){int scene=0;for(var profile:savedProfiles())installOld(profile,SAVED.east(scene++*8),true);need(scene==16,"all source final 1/3 width-height/direction variants installed");world.setBlock(FAILED,block().defaultBlockState(),2);var tag=host(FAILED).saveWithoutMetadata(world.registryAccess());tag.putBoolean(NativeSegmentedItem.RECOVERY,true);tag.putString("FutureFailedSnapshot","inert-native-owner");host(FAILED).loadWithComponents(tag,world.registryAccess());need(host(FAILED).inert()&&!host(FAILED).isChannelMemberActive()&&!host(FAILED).fluidActionsAllowed(),"public canonical failed snapshot remains inert");world.setChunkForced(FAILED.getX()>>4,FAILED.getZ()>>4,true);}
 private static void readOld(){int scene=0;for(var profile:savedProfiles()){BlockPos top=SAVED.east(scene++*8);world.getChunkAt(top);int width=profile.get("width").getAsInt(),height=profile.get("height").getAsInt();for(int x=0;x<width;x++)for(int row=0;row<height;row++){var t=host(top.offset(x,-row,0));need(t!=null&&t.getType()==BuiltInRegistries.BLOCK_ENTITY_TYPE.get(ID)&&t.topOffset()==row&&t.height()==height&&t.column()==x&&t.columnsCount()==width&&t.root()==host(top.east(x)),"actual previous-release group topology survives separate process");need(t.settings().direction==profile.get("direction").getAsInt()&&t.settings().straight&&t.settings().position==2,"actual previous settings survive separate process");}var root=host(top);need(root.saveWithoutMetadata(world.registryAccess()).getCompound("ForgeCaps").getString("Owner").equals("previous-segmented"),"opaque old capabilities survive restart");need(root.containedFluids().get(0).is(net.minecraft.world.level.material.Fluids.WATER)&&root.containedFluids().occupied(1)&&root.containedFluids().get(1).isEmpty(),"known tagged and opaque stationary fluid ownership survives restart");var saved=root.saveWithoutMetadata(world.registryAccess()).getCompound(NativeFluidSlots.KEY);need(saved.getString("FutureFluidSchema").equals("retain-envelope")&&saved.getCompound("Side0").getCompound("Tag").getString("Previous").equals("tagged-water")&&saved.getCompound("Side1").getString("Payload").equals("opaque-fluid"),"exact old tagged/unknown fluid envelope retained");String projection=root.getUpdateTag(world.registryAccess()).toString();need(!projection.contains("ForgeCaps")&&!projection.contains("missing:previous_segmented")&&!projection.contains("FutureFluidSchema"),"public update excludes opaque saved bytes");}world.getChunkAt(FAILED);need(host(FAILED).inert()&&host(FAILED).saveWithoutMetadata(world.registryAccess()).getString("FutureFailedSnapshot").equals("inert-native-owner"),"failed canonical snapshot remains inert and retained across process restart");}
 @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception {if(!phase().startsWith("segmented-canonical-"))return;world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);source=new ArrayList<>();for(String line:Files.readAllLines(Paths.get(System.getProperty("vandorlabs.segmentedCanonicalReference"))))source.add(JsonParser.parseString(line).getAsJsonObject());registrations();if(phase().endsWith("read")){readOld();finish("read");return;}oldLayouts();mining();for(int x=-2;x<5;x++)for(int y=0;y<5;y++)for(int z=-3;z<=3;z++){var p=RUNTIME.offset(x,y,z);world.getChunkAt(p);world.setBlock(p,Blocks.AIR.defaultBlockState(),2);}var held=new ItemStack(item(),32);for(int x=0;x<3;x++){world.getChunkAt(RUNTIME.east(x));world.setBlock(RUNTIME.east(x).below(),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<3;y++)place(RUNTIME.offset(x,y,0),held);}need(held.getCount()==23,"3x3 ordinary survival build owns nine segments");running=true;start=world.getGameTime();}
 @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;need(++ticks<1200,"native canonical timeline timeout stage="+stage+" cycle="+cycle);if(stage==0&&world.getGameTime()-start>=20){for(int x=0;x<3;x++)for(int y=0;y<3;y++){var t=host(RUNTIME.offset(x,y,0));need(t.formed()&&t.height()==3&&t.topOffset()==2-y&&t.column()==x&&t.columnsCount()==3&&t.root()==host(RUNTIME.offset(x,2,0)),"actual ticker forms canonical 3x3 roots/members pos="+t.getBlockPos()+" formed="+t.formed()+" height="+t.height()+" offset="+t.topOffset()+" column="+t.column()+" columns="+t.columnsCount()+" root="+t.root().getBlockPos());}edit(0,0,false);operate(true);stage=1;}
  else if(stage==1&&world.getGameTime()-start>=17){settled(true);operate(false);stage=2;}
  else if(stage==2&&world.getGameTime()-start>=17){settled(false);if(++cycle<8){edit(0,cycle/2,(cycle&1)!=0);operate(true);stage=1;}else{edit(1,0,true);var transmitter=new ItemStack(VandorLabsBootstrap.REDSTONE_TRANSMITTER.get());NativeTransmitterItem.configure(transmitter,ChannelList.of(77701));actor.setItemInHand(InteractionHand.MAIN_HAND,transmitter);need(NativeRedstoneChannels.manualToggle(actor,transmitter),"actual handheld channel source");start=world.getGameTime();stage=3;}}
  else if(stage==3&&world.getGameTime()-start>=3){need(host(RUNTIME.above(2)).targetOpen(),"actual channel opens canonical span");boolean refused=false;try{operate(false);}catch(IllegalArgumentException controlled){refused=true;}need(refused,"positive activation refuses manual close");need(NativeRedstoneChannels.manualToggle(actor,actor.getMainHandItem()),"actual handheld source off");start=world.getGameTime();stage=4;}
  else if(stage==4&&world.getGameTime()-start>=3){need(!host(RUNTIME.above(2)).targetOpen(),"actual channel closes canonical span");saveOld();start=world.getGameTime();stage=5;}
  else if(stage==5&&world.getGameTime()-start>=25)finish("write");
 }
 private static void finish(String name){running=false;world.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][segmented-canonical] "+name+" PASS checks="+checks+" actual public ID/factories/recipe/creative/3x3 placement/menus/8mechanisms/channels/oldNBT/known+opaque fluids/plain loot/restart; real client rendering separate");world.getServer().halt(false);}
